import{_ as n,o as t,c as r,a3 as i}from"./chunks/framework.B9qR_F1m.js";const s="/bilder/zeichnungen.jpg",c=JSON.parse('{"title":"Planung","description":"","frontmatter":{},"headers":[],"relativePath":"bereiche/planung.md","filePath":"bereiche/planung.md"}'),a={name:"bereiche/planung.md"};function o(l,e,g,d,u,h){return t(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="planung" tabindex="-1">Planung <a class="header-anchor" href="#planung" aria-label="Permalink to &quot;Planung&quot;">​</a></h1><p>Taktische Grafiken – CAP-Stationen, Frontlinien, Kill Boxes – zeichnest du hier auf die Karte. Shardwing schreibt sie als <strong>Zeichnungen in die .miz</strong>, sodass sie auf der F10-Karte in DCS erscheinen, und nutzt sie für Kneeboard-Karten und Geo Lines in der Cartridge.</p><p>Nur der Mission Designer sieht diesen Bereich.</p><p><img src="'+s+'" alt="Bereich Planung mit Werkzeugen, Ebenen und einem ausgewählten CAP" loading="lazy"></p><h2 id="werkzeuge" tabindex="-1">Werkzeuge <a class="header-anchor" href="#werkzeuge" aria-label="Permalink to &quot;Werkzeuge&quot;">​</a></h2><p>Links ein Werkzeug wählen und auf die Karte setzen:</p><table tabindex="0"><thead><tr><th>Gruppe</th><th>Grafiken</th></tr></thead><tbody><tr><td><strong>Orbits</strong></td><td><strong>CAP</strong> (Racetrack), <strong>AWACS</strong></td></tr><tr><td><strong>Linien</strong></td><td><strong>FLOT</strong>, <strong>FLET</strong>, <strong>FEBA</strong>, <strong>FSCL</strong>, <strong>CFL</strong>, <strong>NFL</strong>, <strong>RFL</strong>, <strong>PL</strong> (Phase Line), <strong>LD</strong> (Line of Departure), <strong>BDY</strong> (Grenze)</td></tr><tr><td><strong>Gebiete</strong></td><td><strong>KB</strong> (Kill Box), <strong>ROZ</strong>, <strong>NFA</strong>, <strong>RFA</strong>, <strong>MRR</strong></td></tr><tr><td><strong>Punkte (nur F10)</strong></td><td><strong>IP</strong>, <strong>CP</strong> – nur als Zeichnung, ohne Zeiten</td></tr><tr><td><strong>Freie Formen</strong></td><td>Linie, Fläche, Kreis, Rechteck, Pfeil, Text</td></tr><tr><td><strong>Planungspunkte</strong> (Designer, ganz oben)</td><td><strong>RV</strong>, <strong>Marshal</strong>, <strong>Holding</strong>, <strong>CP</strong>, <strong>IP</strong>, <strong>Push</strong>, <strong>Fence</strong>, <strong>TGT</strong> (Zielgebiet), <strong>Fix</strong> (ohne feste Rolle)</td></tr></tbody></table><p>Tanker-Tracks zeichnest du beim Tanker (<em>Flights → Auftrag → Track</em>), Holdings als Planungspunkt <strong>Holding</strong> – so gibt es jedes nur einmal.</p><p>Die Grafiken folgen den NATO-Darstellungen: FLOT und FLET mit Halbkreisen, FEBA mit Dreiecken, Kill Boxes mit Beschriftung.</p><h2 id="bearbeiten" tabindex="-1">Bearbeiten <a class="header-anchor" href="#bearbeiten" aria-label="Permalink to &quot;Bearbeiten&quot;">​</a></h2><ul><li><strong>Anklicken</strong> wählt eine Grafik oder eine bestehende Zeichnung aus der Mission.</li><li>Der <strong>weiße Griff</strong> verschiebt sie, die <strong>kleinen Punkte</strong> formen sie.</li><li>Beim <strong>CAP</strong> stellt der zweite Griff <strong>Kurs und Leglänge</strong> ein.</li><li>Linien und Flächen setzt du Punkt für Punkt; <kbd>Enter</kbd> schließt ab, <kbd>Esc</kbd> bricht ab.</li><li><kbd>Entf</kbd> oder <kbd>⌫</kbd> löscht die Auswahl (auch einen Planungspunkt), <kbd>Esc</kbd> hebt sie auf. Wechselst du die Seite, ist nichts mehr ausgewählt.</li><li><kbd>Esc</kbd> während des Ziehens lässt los: Der Punkt springt zurück, nichts ändert sich. Das gilt auch für Wegpunkte auf der Flight-Seite.</li></ul><p>Im Panel darunter stellst du die gewählte Grafik genau ein: Name und Zusatz (Frequenz, DTG …), Position und Maße in NM, beim CAP Inbound-Kurs, Leglänge und Kurvendurchmesser, beim AR-Track Tanker, Frequenz und TACAN. Auf der Karte trägt ein Tanker- oder AWACS-Track nur Name, Kurs, Leglänge und Höhe: Callsign, Frequenz und TACAN stehen auf der Comm Card und im Reiter Route, denn bei einer Ablösung bleibt der Track, nur der Tanker wechselt. Ältere Tracks verlieren diese Angaben beim Öffnen; einen eigenen Namen oder Zusatz behalten sie. <strong>Farbe</strong> ändert Linie und Beschriftung einer Grafik; <em>Standard</em> nimmt wieder die Farbe der Art. Für Linien gibt es Muster (Linie, Strich-Punkt, Dreiecke, Kreuze, Drahtzaun …), dazu Farbe, Deckkraft, Füllung und Schriftgröße. <strong>Punkte umdrehen</strong> lässt Halbkreise und Dreiecke zur anderen Seite zeigen.</p><h2 id="planungspunkte" tabindex="-1">Planungspunkte <a class="header-anchor" href="#planungspunkte" aria-label="Permalink to &quot;Planungspunkte&quot;">​</a></h2><p>Planungspunkte sind deine Treffpunkte für das Timing: ein Rendezvous, ein Marshal, ein Holding, CP oder IP. Für Spieler-Flights planst du am besten nur noch mit ihnen und den Sollzeiten dort; die Piloten machen daraus im Reiter <a href="./flights#route">Route</a> ihre Steerpoints. Du setzt sie wie eine Grafik. Auch in der Übersicht siehst du sie auf der Karte. Auf der Karte sitzt eine gelbe Raute genau auf der Koordinate, der Name steht daneben (<em>RV ALPHA</em>, <em>MARSHAL ALPHA</em> …); beim Holding ist es ein Punkt.</p><ul><li><strong>Wer ihn sieht.</strong> Ein Flight sieht alle Planungspunkte seiner Seite. Wo er eingetragen ist, steht seine eigene Zeit und Höhe daneben, z. B. <em>MARSHAL ALPHA · H−10 · FL180</em>; die übrigen erscheinen blasser und dienen als Orte für Steerpoints (DTC → NAV → <em>⌖ auf …</em>). Punkte, an denen nur Flights der Gegenseite stehen, und die Zeiten der Gegenseite sieht er nicht. Ins F10 kommen die Punkte nicht (außer dem Holding-Muster). Dazu bekommt der Flight eine <strong>Sollzeit</strong> mit Name, Zeit, Höhe und Koordinate und setzt im Reiter <a href="./flights#route">Route</a> einen Steerpoint dorthin.</li><li><strong>Elevation (optional):</strong> die Höhe des Geländes am Punkt (DED ELEV). Lässt du sie leer, nehmen die Piloten das Gelände darunter.</li><li><strong>Flights an diesem Punkt:</strong> Jeder Flight bekommt seine eigene Zeit, ein Fenster und eine <strong>Höhe</strong> – als FL (<em>180</em>) oder in ft (<em>8000</em>). So sammeln sich mehrere Flights am selben Marshal, ohne dass du den Punkt mehrfach anlegst. <strong>+ Alle Player-Flights</strong> trägt alle Player-Flights der Seite ein, die noch fehlen, jeden einen Schritt später und höher. Ein Flight, der noch kein Timing hat, steht danach mit <strong>Nur Sollzeiten</strong> im Timing, ohne TOT oder Fenster. <ul><li><strong>Zeiten staffeln</strong> – ab der ersten Zeit alle <em>N</em> Minuten (0 = alle gleich).</li><li><strong>Höhen staffeln</strong> – ab FL <em>x</em>, jeder weitere <em>y</em> ft höher.</li><li>Liegen zwei Flights bei etwa gleicher Zeit (bis 10 Minuten auseinander) weniger als 1.000 ft auseinander, steht eine Warnung darunter und unter <em>Prüfungen</em>.</li></ul></li><li><strong>Verschieben oder umbenennen</strong> ändert die Sollzeit bei allen Flights dort.</li><li><strong>TGT:</strong> ein Zielgebiet, rot mit Ring. Im <a href="./timing#ein-flight-im-detail">Timing</a> wählst du ihn als <strong>Ziel</strong> eines Flights (er wird dann dessen Ziel-Punkt) oder als <strong>Gebiet</strong> für TOO. Der Flight sieht den Punkt dann auch ohne Sollzeit dort.</li><li><strong>Fix:</strong> ein Punkt ohne feste Rolle, z. B. ein Wegpunkt, den mehrere Flights fliegen.</li><li><strong>Holding:</strong> Ein Holding-Punkt zeichnet zusätzlich ein <strong>HOLD-Muster</strong>, das alle Flights auf der Karte und im F10 sehen – mit Inbound-Kurs, Leg, Breite und Kurvenrichtung (Standard rechts) und beschriftet mit allen Höhen dort, z. B. <em>FL180–FL230</em>. Die <strong>Farbe</strong> des Musters stellst du am Punkt ein.</li><li><strong>Tanken:</strong> Einen AR-Punkt setzt du nicht mehr selbst. Der Treffpunkt am Tanker ist der <a href="./timing#tanker">AAR-Slot</a>: Der Flight sieht ihn als <em>AR</em> am Beginn des Tracks (P1) auf der Karte und legt im Reiter Route einen Steerpoint dorthin. Ältere AR-Punkte mit <em>Am Track von</em> funktionieren weiter.</li><li><strong>Ohne Zeit:</strong> Ein Haken bei <em>ohne Zeit</em> macht aus der Sollzeit eines Flights einen reinen Ort. Er erscheint nur im Reiter Route, nicht im Timing, nicht auf der Lineup Card und wird nicht geprüft.</li><li><strong>Punkt löschen</strong> lässt die Zeiten der Flights als normale Sollzeiten mit Koordinate stehen.</li></ul><p>Eine Sollzeit mit Ort, die du im <a href="./timing#ein-flight-im-detail">Timing</a> angelegt hast, machst du dort mit <strong>◆ Als Planungspunkt</strong> zu einem Punkt. Die Liste aller Punkte steht links unter <em>Planungspunkte</em> und im Timing unter <em>Treffpunkte</em>.</p><h2 id="ebenen" tabindex="-1">Ebenen <a class="header-anchor" href="#ebenen" aria-label="Permalink to &quot;Ebenen&quot;">​</a></h2><p>DCS kennt fünf Zeichenebenen. Oben links wählst du, auf welche neue Objekte kommen:</p><table tabindex="0"><thead><tr><th>Ebene</th><th>Wer sieht sie auf F10</th></tr></thead><tbody><tr><td><strong>Blue</strong></td><td>nur Blau</td></tr><tr><td><strong>Red</strong></td><td>nur Rot</td></tr><tr><td><strong>Neutral</strong></td><td>nur Neutrale</td></tr><tr><td><strong>Common</strong></td><td>alle</td></tr><tr><td><strong>Author</strong></td><td>nur im Mission Editor</td></tr></tbody></table><p>Die Liste <strong>Ebenen</strong> unten zeigt, wie viele Objekte jede Ebene hat; aufgeklappt siehst du sie einzeln.</p><p><strong>Einheiten zeigen</strong> blendet die Boden-, See- und Static-Gruppen der Mission ein – praktisch, um eine FLOT an echten Stellungen entlang zu ziehen. Mit <strong>Blue</strong>, <strong>Red</strong> und <strong>Neutral</strong> wählst du, welche Seiten erscheinen; alle aus blendet sie wieder aus.</p><h2 id="wo-zeichnungen-auftauchen" tabindex="-1">Wo Zeichnungen auftauchen <a class="header-anchor" href="#wo-zeichnungen-auftauchen" aria-label="Permalink to &quot;Wo Zeichnungen auftauchen&quot;">​</a></h2><ul><li><strong>F10-Karte</strong> in DCS, je nach Ebene</li><li><strong>Kneeboard-Karten</strong>: Lineup Card, Lagekarte, Ausschnitte – jeweils die Ebene der Koalition und Common, so wie der Flight sie auf F10 sähe</li><li><strong>Cartridge</strong>: F-16 als Geo Lines, F/A-18 als FLOT/FAOR/CAP-Punkte – über <strong>Aus Grafik übernehmen</strong> im <a href="./dtc">DTC</a></li></ul>',23)])])}const k=n(a,[["render",o]]);export{c as __pageData,k as default};
